public static void main(String[] args) {
    if (args.length == 0) {
        System.out.println("Please provide an input string.");
        return;
    }

    String S = args[0];
    Set<String> uniqueSubstrings = new HashSet<String>();

    for (int i = 0; i < S.length(); i++) {
        for (int j = i; j < S.length(); j++) {
            String newS = S.substring(i, j + 1);
            uniqueSubstrings.add(newS);
        }
    }

    System.out.println(uniqueSubstrings.size());
}
